SELECT analytics_order_facts.category, COUNT(DISTINCT analytics_order_facts.order_id) AS order_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2024 AND analytics_order_facts.month = 9 AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'small_business' AND analytics_order_facts.category = 'category_07' GROUP BY analytics_order_facts.category ORDER BY order_count DESC, analytics_order_facts.category ASC LIMIT 10
